//go:build linux

package productsession

import (
	"encoding/json"
	"os"
	"os/exec"
	"path/filepath"
	"testing"

	"tbound/supervisor/internal/audit"
)

// The frozen journal was written by ccc7bb48's catalog and OperatorResolve,
// not regenerated by the reader under test.
func TestOperatorResolvedDevCatalogReplays(t *testing.T) {
	path := os.Getenv("TB_OPERATOR_DEV_CATALOG")
	if path == "" {
		data, err := os.ReadFile("testdata/operator-resolved-ccc7bb48.jsonl")
		if err != nil {
			t.Fatal(err)
		}
		path = filepath.Join(privateDir(t), "catalog.jsonl")
		if err := os.WriteFile(path, data, 0600); err != nil {
			t.Fatal(err)
		}
		child := exec.Command(os.Args[0], "-test.run=^TestOperatorResolvedDevCatalogReplays$", "-test.count=1")
		child.Env = append(os.Environ(), "TB_OPERATOR_DEV_CATALOG="+path)
		if out, err := child.CombinedOutput(); err != nil {
			t.Fatalf("fresh-process dev catalog replay: %v\n%s", err, out)
		}
		return
	}
	journal, err := audit.OpenExisting(path)
	if err != nil {
		t.Fatal(err)
	}
	trace, err := journal.Trace()
	if err != nil {
		t.Fatal(err)
	}
	if err := journal.Close(); err != nil {
		t.Fatal(err)
	}
	last := trace.Records[len(trace.Records)-1].Event
	var record operatorResolvedRecord
	if last.Kind != "product_turn_operator_resolved" || json.Unmarshal(last.Data, &record) != nil {
		t.Fatalf("fixture has no final operator resolution: %+v", last)
	}
	c := openAt(t, path, signedRegistration(t, nil))
	turn, ok := c.Turn(record.TurnID)
	if !ok || turn.State != StateTerminal || turn.Outcome != OutcomeAbandoned || turn.TerminalReason != ReasonOperatorResolved || turn.ContextEligible || len(turn.Receipt) != 0 || turn.Usage != turn.Reservation || turn.Refund != (Budget{}) {
		t.Fatalf("dev operator resolution replayed incorrectly: %+v", turn)
	}
	s, err := c.Session(uid1, turn.SessionID)
	if err != nil || s.Blocked || s.Consumed != turn.Reservation || s.Reserved != (Budget{}) {
		t.Fatalf("resolved session: %+v %v", s, err)
	}
	next := mustSubmit(t, c, uid1, s.ID, s.Revision, "after-dev-resolution", "continue")
	if next.PredecessorTurnID != "" || next.PredecessorReceiptDigest != "" {
		t.Fatalf("abandoned dev turn became context: %+v", next)
	}
}
